            var props=fields.Select(f=>(f,Guess(f))).ToArray();
            if(kind=="platform_account")props=props.Append(("assignments",A(AssignmentRow()))).Append(("relationship",S())).ToArray();
            schemas.Add(OpsRow(props));
        }
        schemas.Add(Free());
        return new(){AnyOf=schemas};
    }
